provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "private_subnet" {
  vpc_id           = aws_vpc.main_vpc.id
  cidr_block       = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "public_subnet" {
  vpc_id           = aws_vpc.main_vpc.id
  cidr_block       = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_dax_subnet_group" "main_dax_subnet_group" {
  name        = "main-dax-subnet-group"
  subnet_ids = [aws_subnet.private_subnet.id, aws_subnet.public_subnet.id]
}

resource "aws_db_subnet_group" "main_db_subnet_group" {
  name        = "main-db-subnet-group"
  subnet_ids = [aws_subnet.private_subnet.id, aws_subnet.public_subnet.id]
}

resource "aws_security_group" "private_sg" {
  name   = "private-sg"
  vpc_id = aws_vpc.main_vpc.id

  ingress {
    from_port   = 53
    to_port     = 53
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "public_sg" {
  name   = "public-sg"
  vpc_id = aws_vpc.main_vpc.id

  ingress {
    from_port   = 53
    to_port     = 53
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_route53_zone" "private_zone" {
  name = "private.example.com"
}

resource "aws_route53_zone" "public_zone" {
  name = "public.example.com"
}

resource "aws_route53_record" "private_record" {
  name    = "internal"
  type    = "A"
  zone_id = aws_route53_zone.private_zone.id

  alias {
    evaluate_target_health = true
    name                  = aws_db_instance.internal.endpoint.address
    zone_id                = aws_route53_zone.private_zone.zone_id
  }
}

resource "aws_route53_record" "public_record" {
  name    = "public"
  type    = "A"
  zone_id = aws_route53_zone.public_zone.id

  alias {
    evaluate_target_health = true
    name                  = aws_db_instance.public.endpoint.address
    zone_id                = aws_route53_zone.public_zone.zone_id
  }
}

resource "aws_db_instance" "internal" {
  instance_class = "t3.micro"
  db_subnet_group_name = aws_db_subnet_group.main_db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.private_sg.id]
  engine = "mysql"
  engine_version = "5.7"
