```hcl
provider "aws" {
  region = "us-west-2"  # Example region, adjust as needed
}

resource "aws_route53_zone" "main" {
  name = "main.example.com"
}

resource "aws_route53_record" "eb-env" {
  name     = "eb-env.main.example.com"
  type     = "A"
  zone_id = aws_route53_zone.main.zone_id
  alias {
    evaluate_target_health = true
    name                  = aws_elastic_beanstalk_environment.eb-env.elastic_ip
    zone_id               = aws_route53_zone.main.zone_id
  }
}

resource "aws_iam_role" "eb_ec2_role" {
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_s3_bucket" "examplebucket_object" {
  bucket = "examplebucket-object-${random_string.random_suffix.result}"
  acl    = "private"

  lifecycle_rule {
    enabled = true
    expiration {
      days = 30
    }
  }
}

resource "aws_elastic_beanstalk_application" "myapp" {
  name = "myapp"
}

resource "aws_elastic_beanstalk_application_version" "version" {
  application   = aws_elastic_beanstalk_application.myapp.name
  bucket         = aws_s3_bucket.examplebucket_object.bucket
  key           = "index.html"
  name          = "version"
  description = "Initial version of the application"
}

resource "random_string" "random_suffix" {
  length = 8
  special = false
}
```

This Terraform program creates the necessary AWS resources to manage a domain using Route 53, directs traffic to an Elastic Beanstalk environment, and includes IAM roles and an S3 bucket. The program uses the provided prompt and the typed provider contract to ensure compliance with the requirements.

