provider "aws" {
  region = "us-west-2" # Default region for us_west
}

variable "us_west_app_name" {
  default = "us_west_app"
}

variable "us_west_env_name" {
  default = "us_west_env"
}

variable "eu_central_app_name" {
  default = "eu_central_app"
}

variable "eu_central_env_name" {
  default = "eu_central_env"
}

resource "aws_s3_bucket" "elastic_beanstalk_bucket" {
  bucket = "elastic-beanstalk-bucket-${var.us_west_app_name}-${var.eu_central_app_name}"
  acl    = "private"
}

resource "aws_s3_bucket_website" "elastic_beanstalk_website" {
  bucket = aws_s3_bucket.elastic_beanstalk_bucket.bucket
  index_document {
    suffix = "index.html"
  }
}

resource "aws_elastic_beanstalk_application" "us_west_app" {
  name = var.us_west_app_name
}

resource "aws_elastic_beanstalk_environment" "us_west_env" {
  application = aws_elastic_beanstalk_application.us_west_app.name
  name        = var.us_west_env_name
  platform_arn = "arn:aws:elasticbeanstalk:${var.region}:aws:platform/web/serverless-2.x"
  version_label = "v1"
}

resource "aws_elastic_beanstalk_application" "eu_central_app" {
  name = var.eu_central_app_name
}

resource "aws_elastic_beanstalk_environment" "eu_central_env" {
  application = aws_elastic_beanstalk_application.eu_central_app.name
  name        = var.eu_central_env_name
  platform_arn = "arn:aws:elasticbeanstalk:${var.region}:aws:platform/web/serverless-2.x"
  version_label = "v1"
}

resource "aws_route53_zone" "us_west_zone" {
  name = "us-west.example.com"
}

resource "aws_route53_record" "us_west_record" {
  name     = "us-west.example.com"
  type     = "A"
  zone_id  = aws_route53_zone.us_west_zone.zone_id
  alias {
    evaluate_target_health = true
    name                  = aws_elastic_beanstalk_environment.us_west_env.cname
    zone_id               = aws_route53_zone.us_west_zone.zone_id
  }
}

resource "aws_route53_zone" "eu_central_zone" {
  name = "eu-central.example.com"
}

resource "aws_route53_record" "eu_central_record" {
  name     = "eu-central.example.com"
  type     = "A"
  zone_id  = aws_route53_zone.eu_central_zone.zone_id
  alias {
    evaluate_target_health = true
    name                  = aws_elastic_beanstalk_environment.eu_central_env.cname
    zone_id               = aws_route53_zone.eu_central_zone.zone_id
  }
}
```

