  acl    = "private"
}

resource "aws_s3_bucket_policy" "web_app_bucket_policy" {
  bucket = aws_s3_bucket.web_app_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action   = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "${aws_s3_bucket.web_app_bucket.arn}/*",
          "${aws_s3_bucket.web_app_bucket.arn}"
        ]
      }
    ]
  })
}

resource "aws_cloudfront_distribution" "web_app_distribution" {
  enabled = true

  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = aws_s3_bucket.web_app_bucket.id
    viewer_protocol_policy = "allow-all"

    response_headers_policy_id = aws_cloudfront_response_headers_policy.web_app_response_headers_policy.id
  }

  origin {
