```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseDeliveryServiceRolePolicy"
  role       = aws_iam_role.firehose_role.name
}

resource "aws_kinesis_firehose_delivery_stream" "new_relic_firehose" {
  name = "new_relic_firehose"

  destination {
    http_endpoint {
      url = "https://logs-api.newrelic.com/v1/accounts/<account_id>/log-events"

      access_key {
        access_key_id     = "YOUR_ACCESS_KEY_ID"
        secret_access_key = "YOUR_SECRET_ACCESS_KEY"
      }

      buffering_interval = 60
      buffering_size    = 1024
      retry_duration    = 60
      s3_backup_mode    = "Enabled"
    }
  }

  tags = {
    Name = "new_relic_firehose"
  }
}
```

**Explanation**:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **IAM Role**: An IAM role named `firehose_role` is created with permissions to assume the `AWSFirehoseDeliveryServiceRolePolicy`.
- **IAM Policy Attachment**: A policy attachment is added to the role to grant the necessary permissions.
- **Kinesis Firehose Delivery Stream**: A delivery stream named `new_relic_firehose` is created with an HTTP endpoint destination to New Relic. The `access_key` block is used to provide credentials for authentication. The `buffering_interval` and `retry_duration` are set to 60 seconds, and `s3_backup_mode` is enabled. Tags are applied to the delivery stream for easy identification.

