  }
}

resource "aws_iam_role" "example_iam_role" {
  name = var.iam_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  inline_policy {
    name = "example_inline_policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "ec2:DescribeInstances",
            "ec2:RunInstances"
          ]
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_opensearchserverless_access_policy" "example_access_policy" {
  name   = var.access_policy_name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = var.principal_arn
        }
        Action = [
          "opensearchserverless:DescribeDomain",
          "opensearchserverless:GetDomainConfig",
          "opensearchserverless:ListDomains"
        ]
        Resource = "arn:aws:opensearchserverless:*:*:domain/example-domain"
      }
    ]
  })
}

resource "aws_ssoadmin_application_access_scope" "example_access_scope" {
  application_arn = var.application_arn
  scope = var.scope

  authorized_targets = [
    {
      type = "namespace"
      value = "example-namespace"
    }
  ]
}
