```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "terraform_state_bucket" {
  bucket = "terraform-state-bucket-${var.account_id}-${var.region}"
  acl     = "private"
  versioning {
    enabled = true
  }
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
  block_public_access {
    block_public_acls           = true
    ignore_public_acls         = true
    restrict_public_buckets    = true
    block_public_objects       = true
    block_public_objects_all   = true
    restrict_public_objects_acl = true
  }
  lifecycle_rule {
    id      = "delete-old-objects"
    enabled = true
    expiration {
      days = 30
    }
  }
}

resource "aws_dynamodb_table" "terraform_lock_table" {
  name = "terraform-lock-table-${var.account_id}-${var.region}"

  billing_mode = "PAY_PER_REQUEST"

  hash_key = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  global_secondary_index {
    name           = "LockIDIndex"
    hash_key       = "LockID"
    projection_type = "ALL"
  }

  on_demand_throughput {
    read_capacity_units   = 5
    write_capacity_units = 5
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state_bucket_encryption" {
  bucket = aws_s3_bucket.terraform_state_bucket.id
}

resource "aws_s3_bucket_versioning" "terraform_state_bucket_versioning" {
  bucket = aws_s3_bucket.terraform_state_bucket.id
}

resource "aws_ebs_snapshot_block_public_access" "terraform_state_bucket_public_access" {
  state = "enabled"
}

resource "aws_ec2_image_block_public_access" "terraform_state_bucket_image_public_access" {
  state = "enabled"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **S3 Bucket**: 
  - The bucket is named `terraform-state-bucket-${var.account_id}-${var.region}`.
  - It uses private ACLs and versioning.
  - Server-side encryption is enabled with AES256.
  - Public access is restricted.
  - A lifecycle rule deletes objects older than 30 days.
- **DynamoDB Table**:
  - The table is named `terraform-lock-table-${var.account_id}-${var.region}`.
  - It uses PAY_PER_REQUEST billing mode.
  - The hash key is `LockID`.
  - A global secondary index is created on `LockID`.
  - On-demand throughput is set to 5 units for reads and writes.
- **Block Public Access**:
  - Both S3 bucket and EC2 image block public access are enabled.

