  bucket = aws_s3_bucket.memcached_data_bucket.bucket
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action   = ["s3:GetObject"]
        Resource = ["arn:aws:s3:::${aws_s3_bucket.memcached_data_bucket.bucket}/*"]
      }
    ]
  })
}

resource "aws_security_group" "memcached_sg" {
  name        = var.memcached_sg_name
  description = "Security group for Memcached instances"

  ingress {
    from_port   = 11211
    to_port     = 11211
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group_rule" "memcached_sg_inbound" {
  security_group_id = aws_security_group.memcached_sg.id
  from_port         = 11211
  to_port           = 11211
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_instance" "memcached_instance" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = var.memcached_instance_type
  subnet_id      = aws_subnet.default.id
  security_groups = [aws_security_group.memcached_sg.id]
  tags = {
    Name = "memcached-instance-${var.random_suffix}"
  }
}

resource "aws_autoscaling_group" "memcached_asg" {
  name                 = "memcached-asg-${var.random_suffix}"
  max_size             = 3
  min_size             = 1
  desired_capacity     = 2
  launch_configuration = aws_launch_configuration.memcached_lc.name
  availability_zones = ["us-east-1a", "us-east-1b"]

  health_check_grace_period = 300
  health_check_type        = "ELB"

  tag {
    key                 = "Name"
    value               = "memcached-asg-${var.random_suffix}"
    propagate_at_launch = true
  }
}

resource "aws_launch_configuration" "memcached_lc" {
  image_id        = "ami-0c55b159cbfafe1f0"
  instance_type = var.memcached_instance_type
  key_name        = "my-key-pair"
  security_groups = [aws_security_group.memcached_sg.id]

  user_data = <<-EOF
    #!/bin/bash
    yum update -y
    yum install -y memcached
    systemctl start memcached
    systemctl enable memcached
  EOF

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_elb" "memcached_elb" {
  name               = var.memcached_elb_name
  subnets            = [aws_subnet.default.id]
  security_groups     = [aws_security_group.memcached_sg.id]
  listeners          = [
    {
      instance_port     = 11211
      instance_protocol = "tcp"
      lb_port           = 11211
      lb_protocol       = "tcp"
    }
  ]
  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    interval            = 30
    target              = "HTTP:11211/"
    timeout             = 5
  }
  cross_zone_load_balancing = true
  idle_timeout             = 60
}

resource "aws_elb_attachment" "memcached_elb_attachment" {
  elb       = aws_elb.memcached_elb.id
  instance = aws_instance.memcached_instance.id
}

resource "aws_route53_record" "memcached_dns_record" {
  name       = var.memcached_dns_record_name
  type       = var.memcached_dns_record_type
  zone_id    = var.memcached_dns_record_zone_id
  ttl        = 300
  records    = [aws_elb.memcached_elb.dns_name]
}
```

