```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name       = "my-msk-cluster"
  kafka_version      = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
    instance_type  = "t3.micro"
    security_groups = ["sg-12345678"]

    az_distribution = "DEFAULT"
  }

  logging_info {
    broker_logs {
      cloud_watch_logs {
        enabled = true
        log_group = "/aws/msk/my-msk-cluster/logs"
      }
    }
  }
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name = "my-msk-firehose"

  destination {
    s3 {
      bucket_arn = aws_s3_bucket.my-bucket.arn
      role_arn   = aws_iam_role.msk-firehose-role.arn

      buffering_interval  = 60
      buffering_size     = 128
      compression_format = "GZIP"
      prefix             = "msk-log/"
    }
  }
}

resource "aws_s3_bucket" "my-bucket" {
  bucket = "my-msk-bucket-${var.environment}"
  acl    = "private"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "msk-firehose-role" {
  name = "msk-firehose-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.my-bucket.arn}",
          "${aws_s3_bucket.my-bucket.arn}/*"
        ]
      }
    ]
  })
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **MSK Cluster**: 
  - A managed MSK cluster is created with the name `my-msk-cluster`.
  - It uses Kafka version `2.8.1` and has 3 broker nodes.
  - Each broker node is placed in three subnets (`subnet-12345678`, `subnet-23456789`, `subnet-34567890`) and runs on `t3.micro` instances.
  - Enhanced monitoring is enabled, and logs are sent to CloudWatch Logs.
- **Kinesis Firehose Delivery Stream**:
  - A Kinesis Firehose delivery stream named `my-msk-firehose` is created.
  - It sends logs to an S3 bucket (`my-msk-bucket-${var.environment}`).
  - The S3 bucket is configured with a lifecycle policy to prevent accidental deletion.
- **S3 Bucket**:
  - An S3 bucket named `my-msk-bucket-${var.environment}` is created with a private ACL.
  - The bucket is configured with a lifecycle policy to prevent accidental deletion.
- **IAM Role**:
  - An IAM role named `msk-firehose-role-${var.environment}` is created with permissions to put, get, and list objects in the S3 bucket.
  - The role assumes the `firehose.amazonaws.com` service principal.

