provider "aws" {
  region = "us-west-2"
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "kafka_version" {
  description = "Version of Kafka for the MSK cluster"
  default     = "2.8.1"
}

variable "number_of_broker_nodes" {
  description = "Number of broker nodes in the MSK cluster"
  default     = 3
}

variable "encryption_key_arn" {
  description = "ARN of the KMS key for encryption at rest"
  default     = "arn:aws:kms:us-west-2:123456789012:key/1234abcd-12ab-34cd-56ef-1234567890ab"
}

resource "aws_s3_bucket" "msk_cluster_encryption_bucket" {
  bucket = "${var.msk_cluster_name}-encryption-bucket"

  server_side_encryption_configuration {
    rule {
      bucket_key_enabled = true
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_cluster_encryption_config" {
  bucket = aws_s3_bucket.msk_cluster_encryption_bucket.id

  apply_server_side_encryption_by_default {
    kms_master_key_id = var.encryption_key_arn
    sse_algorithm    = "aws:kms"
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name
  kafka_version = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  encryption_info {
    encryption_at_rest_kms_key_arn = var.encryption_key_arn
  }

  tags = {
    Name = var.msk_cluster_name
  }
}
```

