provider "aws" {
  region = "us-east-1"
}

variable "lambda_function_name" {
  default = "msk-cluster-lambda"
}

variable "iam_role_name" {
  default = "msk-cluster-iam-role"
}

resource "aws_iam_role" "msk_cluster_iam_role" {
  name = var.iam_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_lambda_function" "msk_cluster_lambda" {
  function_name = var.lambda_function_name
  role = aws_iam_role.msk_cluster_iam_role.arn
  handler = "index.handler"
  runtime = "python3.8"
  code = filebase64sha256("lambda_function.py")
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = "msk-cluster"
  kafka_version = "2.8.2"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
    instance_type = "t3.micro"
    security_groups = ["sg-12345678"]
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group = "/aws/msk/msk-cluster"
      }
    }
  }
}
