```hcl
provider "aws" {
  region = "us-east-1"
}

variable "msk_cluster_name" {
  default = "my-msk-cluster"
}

variable "kafka_version" {
  default = "2.8.1"
}

variable "number_of_broker_nodes" {
  default = 3
}

variable "encryption_at_rest_kms_key_arn" {
  default = "arn:aws:kms:us-east-1:123456789012:key/12345678-1234-1234-1234-123456789012"
}

variable "log_group_name" {
  default = "msk-logs"
}

variable "s3_bucket_name" {
  default = "msk-logs-bucket"
}

variable "firehose_delivery_stream_name" {
  default = "msk-logs-firehose"
}

resource "aws_cloudwatch_log_group" "msk_logs" {
  name = var.log_group_name
  retention_in_days = 30
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = var.s3_bucket_name
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = var.encryption_at_rest_kms_key_arn
        sse_algorithm = "aws:kms"
      }
    }
  }
}

resource "aws_kinesis_firehose_delivery_stream" "msk_logs_firehose" {
  name = var.firehose_delivery_stream_name
  destination = "s3"
  s3_configuration {
    bucket_arn = aws_s3_bucket.msk_logs_bucket.arn
    role_arn = aws_iam_role.msk_logs_firehose_role.arn
    buffering_interval = 60
    buffering_size = 512
    compression_format = "GZIP"
  }
  logging_configuration {
    enabled = true
    log_group_name = aws_cloudwatch_log_group.msk_logs.name
    log_stream_name = aws_kinesis_firehose_delivery_stream.msk_logs_firehose.name
  }
  processing_configuration {
    enabled = true
  }
  processors {
    type = "Lambda"
    parameters {
      parameter_name = "LambdaArn"
      parameter_value = "arn:aws:lambda:us-east-1:123456789012:function:msk-logs-lambda"
    }
  }
}

resource "aws_iam_role" "msk_logs_firehose_role" {
  name = "${var.msck_cluster_name}-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_logs_firehose_policy_attachment" {
  role = aws_iam_role.msk_logs_firehose_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseDeliveryServiceRolePolicy"
}
```

