```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "autograder_results" {
  bucket = "autograder-results-${var.student_id}"
  acl    = "private"
}

resource "aws_codebuild_project" "autograder_project" {
  name               = "cs-class-autograder-${var.student_id}"
  service_role       = aws_iam_role.autograder_role.arn
  badge_enabled     = false
  build_timeout     = 60
  concurrent_build_limit = 1
  description       = "Autograder for CS class"
  encryption_key     = aws_kms_key.autograder_key.arn
  source_version     = var.git_commit_hash
  tags = {
    Class = "CS"
    Assignment = "Autograder"
  }

  artifacts {
    type = "S3"
    location = aws_s3_bucket.autograder_results.bucket
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image         = "aws/codebuild/standard:4.0"
    type          = "LINUX_CONTAINER"
  }

  source {
    type = "GITHUB"
    location = "https://github.com/example/cs-class.git"
    report_build_status = true
  }

  notification_config {
    notifications {
      type = "WEBHOOK"
      target_arn = aws_sns_topic.autograder_notifications.arn
    }
  }
}

resource "aws_iam_role" "autograder_role" {
  name = "cs-class-autograder-role-${var.student_id}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "autograder_policy_attachment" {
  role       = aws_iam_role.autograder_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildServiceRole"
}

resource "aws_kms_key" "autograder_key" {
  description = "KMS key for autograder"
}

resource "aws_sns_topic" "autograder_notifications" {
  name = "cs-class-autograder-notifications-${var.student_id}"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-west-2` region.
- **S3 Bucket**: An S3 bucket named `autograder-results-${var.student_id}` is created to store the build artifacts.
- **CodeBuild Project**: A CodeBuild project named `cs-class-autograder-${var.student_id}` is defined. It uses the `aws/codebuild/standard:4.0` image and runs on a `BUILD_GENERAL1_SMALL` compute type. The project sources code from a GitHub repository and stores the results in the S3 bucket.
- **IAM Role**: An IAM role `cs-class-autograder-role-${var.student_id}` is created to allow CodeBuild to assume the role. This role is attached to the CodeBuild project.
- **KMS Key**: A KMS key is created to encrypt the build artifacts.
- **SNS Topic**: An SNS topic is created to receive notifications about the build status.

