  name           = "autograder-${var.student_id}"
  service_role   = aws_iam_role.autograder_role.arn
  badge_enabled  = true
  build_timeout  = 60
  concurrent_build_limit = 1
  description   = "Runs student code and stores results"
  encryption_key = aws_kms_key.autograder_key.arn
  source        {
    type     = "GitHub"
    location = "https://github.com/${var.student_username}/student-code.git"
    git_clone_depth = 1
    report_build_status = true
  }
  artifacts {
    type = "S3"
    location = aws_s3_bucket.autograder_results.bucket
    name = "autograder-results-${var.student_id}"
  }
  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image       = "aws/codebuild/standard:4.0"
    type        = "LINUX_CONTAINER"
  }
  cache {
    type = "LOCAL_DOCKER_LAYER_CACHE"
  }
  logs_config {
    cloudwatch_logs {
      log_group_name = "/aws/codebuild/autograder-${var.student_id}"
    }
  }
  secondary_sources {
    source_identifier = "secondary-source"
    type             = "GitHub"
    location         = "https://github.com/${var.student_username}/test-scripts.git"
    report_build_status = true
  }
  secondary_artifacts {
    artifact_identifier = "secondary-artifact"
    type                = "S3"
    location            = aws_s3_bucket.autograder_results.bucket
    name                = "test-scripts-${var.student_id}"
  }
}

resource "aws_iam_role" "autograder_role" {
  name = "autograder-role-${var.student_id}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "autograder_policy" {
  name = "autograder-policy-${var.student_id}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.autograder_results.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "autograder_role_policy_attachment" {
  role       = aws_iam_role.autograder_role.name
  policy_arn = aws_iam_policy.autograder_policy.arn
}

resource "aws_kms_key" "autograder_key" {
  description = "KMS key for CodeBuild encryption"
}
```

### Explanation:
- **Provider Configuration**: Sets the AWS region to `us-west-2`.
- **S3 Bucket**: Creates an S3 bucket to store autograder results. The bucket name includes a student ID to ensure uniqueness.
- **CodeBuild Project**: Configures a CodeBuild project to run student code from a GitHub repository. It uses a private S3 bucket for storing results and a KMS key for encryption.
- **IAM Role**: Defines an IAM role with permissions to assume the CodeBuild service role and access the S3 bucket.
- **IAM Policy**: Grants permissions to read and write objects in the S3 bucket.
- **IAM Role Policy Attachment**: Attaches the IAM policy to the IAM role.
- **KMS Key**: Creates a KMS key for encrypting CodeBuild artifacts.

