provider "aws" {
  region = "us-west-2"
}

variable "cat_picture_bucket_name" {
  default = "cat-pictures-bucket"
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = var.cat_picture_bucket_name
  acl     = "private"

  cors_rule {
    allowed_methods   = ["GET", "PUT"]
    allowed_origins  = ["*"]
    allowed_headers  = ["*"]
    expose_headers   = ["ETag"]
    max_age_seconds = 3000
  }

  grant {
    type        = "principal"
    principal   = "arn:aws:iam::123456789012:user/cat-api-gateway"
    permissions = ["s3:GetObject", "s3:PutObject"]
  }

  lifecycle_rule {
    enabled = true
    prefix  = "uploads/"
    expiration {
      days = 30
    }
  }
}

resource "aws_api_gateway_rest_api" "cat_api_gateway" {
  name = "cat-api-gateway"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  resource {
    path_part = "cat"

    method {
      http_method = "GET"
      authorization_type = "NONE"
      integration {
        type = "HTTP_PROXY"
        uri = "https://s3.amazonaws.com/${aws_s3_bucket.cat_pictures_bucket.bucket}"
        integration_http_method = "GET"
      }
    }

    method {
      http_method = "POST"
      authorization_type = "NONE"
      integration {
        type = "HTTP_PROXY"
        uri = "https://s3.amazonaws.com/${aws_s3_bucket.cat_pictures_bucket.bucket}"
        integration_http_method = "PUT"
      }
    }
  }
}
