provider "aws" {
  region = "us-west-2"
}

variable "ec2_instance_type" {
  default = "t3.micro"
}

variable "backup_plan_name" {
  default = "DailyBackupPlan"
}

variable "backup_vault_name" {
  default = "DailyBackupVault"
}

resource "aws_instance" "ec2_instance" {
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI ID
  instance_type = var.ec2_instance_type
  associate_public_ip_address = true
  tags = {
    Name = "DailyBackupInstance"
  }
}

resource "aws_backup_plan" "backup_plan" {
  name = var.backup_plan_name

  rule {
    rule_name              = "DailyBackupRule"
    target_vault_name     = var.backup_vault_name
    schedule_expression   = "cron(0 0 * * ? *)" # Daily at midnight
    lifecycle {
      retain_until_date = time.add(time.now(), 30d) # Retain backups for 30 days
    }
  }
}

resource "aws_backup_selection" "backup_selection" {
  name         = "DailyBackupSelection"
  plan_id       = aws_backup_plan.backup_plan.id
  iam_role_arn = aws_iam_role.backup_role.arn

  resources = [
    aws_instance.ec2_instance.id
  ]
}

resource "aws_iam_role" "backup_role" {
  name = "DailyBackupRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_role_policy_attachment" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicy"
}
