    cached_methods   = ["GET", "HEAD"]
    target_origin_id = aws_cloudfront_origin_access_control.video_streaming_site_oac.id
    viewer_protocol_policy = "allow-all"
  }
  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
  viewer_certificate {
    ssl_support_method = "sni-only"
    cloudfront_default_certificate = true
  }
  tags = {
    Name = "Video Streaming Site Distribution"
  }
}

resource "aws_route53_zone" "video_streaming_site_zone" {
  name = var.domain_name
  tags = {
    Name = "Video Streaming Site Zone"
  }
}

resource "aws_s3_bucket" "video_streaming_site_bucket" {
  bucket = var.s3_bucket_name
  acl     = "private"

  cors_rule {
    allowed_methods   = ["GET", "HEAD", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    allowed_headers = ["*"]
    expose_headers = ["ETag"]
    max_age_seconds = 3000
  }

  lifecycle_rule {
    enabled = true
    id      = "DeleteExpiredObjects"
    expiration {
      days = 30
    }
  }

  tags = {
    Name = "Video Streaming Site Bucket"
  }
}
