provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "The domain name for the video streaming site."
  default     = "example.com"
}

variable "instance_type" {
  description = "The type of EC2 instance to use."
  default     = "t3.micro"
}

variable "num_instances" {
  description = "The number of EC2 instances to deploy."
  default     = 3
}

resource "aws_vpc" "video_streaming_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "video_streaming_subnet" {
  vpc_id           = aws_vpc.video_streaming_vpc.id
  cidr_block       = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "video_streaming_sg" {
  vpc_id = aws_vpc.video_streaming_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_elb" "video_streaming_elb" {
  name               = "video-streaming-elb"
  subnets             = [aws_subnet.video_streaming_subnet.id]
  security_groups     = [aws_security_group.video_streaming_sg.id]
  internal           = false
  listeners {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "http"
  }
  health_check {
    healthy_threshold   = 2
    interval            = 30
    target              = "HTTP:80/"
    timeout             = 5
    unhealthy_threshold = 2
  }
}

resource "aws_alb_target_group" "video_streaming_target_group" {
  name                  = "video-streaming-target-group"
  port                  = 80
  protocol              = "HTTP"
  vpc_id                = aws_vpc.video_streaming_vpc.id
  target_type           = "instance"
  health_check_path    = "/"
  health_check_interval = 30
  health_check_timeout  = 5
  health_check_protocol = "HTTP"
  health_check_port    = "traffic-port"
  deregistration_delay = 300
}

resource "aws_route53_zone" "video_streaming_zone" {
  name = var.domain_name
}

resource "aws_route53_record" "video_streaming_record" {
  name    = var.domain_name
  type    = "A"
  zone_id = aws_route53_zone.video_streaming_zone.id
  alias {
    name                   = aws_elb.video_streaming_elb.dns_name
    zone_id                 = aws_elb.video_streaming_elb.zone_id
    evaluate_target_health = true
  }
}

resource "aws_instance" "video_streaming_instance" {
  count               = var.num_instances
  ami                 = "ami-0c55b159cbfafe1f0" # Example AMI ID
