```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_instance_class" {
  description = "The class of the PostgreSQL database instance."
  default     = "db.t3.micro"
}

variable "db_instance_name" {
  description = "The name of the PostgreSQL database instance."
  default     = "my-postgres-db"
}

variable "db_subnet_group_name" {
  description = "The name of the DB subnet group."
  default     = "my-db-subnet-group"
}

variable "vpc_id" {
  description = "The ID of the VPC where the database instance will be placed."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "The IDs of the subnets in the VPC where the database instance will be placed."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_ids" {
  description = "The IDs of the security groups for the database instance."
  default     = ["sg-12345678", "sg-87654321"]
}

resource "aws_vpc" "example_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example_subnet" {
  count           = length(var.subnet_ids)
  vpc_id          = var.vpc_id
  cidr_block       = cidrsubnet(var.vpc_cidr_block, 24, count.index)
  availability_zone = "us-west-2a"

  timeouts {
    create = "10m"
    delete = "10m"
  }
}

resource "aws_db_subnet_group" "example_db_subnet_group" {
  name        = var.db_subnet_group_name
  subnet_ids = var.subnet_ids
}

resource "aws_rds_custom_db_engine_version" "example_db_engine_version" {
  engine         = "postgres"
  engine_version = "13.6"
}

resource "aws_db_instance" "example_db_instance" {
  engine                  = "postgres"
  engine_version          = aws_rds_custom_db_engine_version.example_db_engine_version.engine_version
  instance_class          = var.db_instance_class
