```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lightsail_instance" "lightsail_db_instance" {
  availability_zone = "us-east-1a"
  blueprint_id       = "ubuntu_20_04"
  bundle_id         = "nano_1_0"
  name              = "lightsail-db-instance"

  # Optional: Add any additional configuration as needed
}

resource "aws_db_instance" "postgres_db" {
  instance_class = "db.t3.micro"

  # Required attributes
  allocated_storage = 20
  engine           = "postgres"
  engine_version   = "13.6"
  name             = "postgres-db"

  # Optional attributes
  apply_immediately = true
  auto_minor_version_upgrade = true
  backup_retention_period = 7
  backup_window = "07:00-09:00"
  character_set_name = "utf8mb4"
  copy_tags_to_snapshot = true
  db_subnet_group_name = aws_db_subnet_group.postgres_db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.postgres_db_sg.id]

  # Nested blocks
  s3_import {
    bucket_name = "my-s3-bucket"
    ingestion_role = aws_iam_role.postgres_db_role.arn
    source_engine = "postgres"
    source_engine_version = "13.6"
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}

resource "aws_db_subnet_group" "postgres_db_subnet_group" {
  name = "postgres-db-subnet-group"
  subnet_ids = [aws_subnet.postgres_db_subnet.id]
}

resource "aws_subnet" "postgres_db_subnet" {
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  vpc_id = aws_vpc.postgres_db_vpc.id
}

resource "aws_vpc" "postgres_db_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_security_group" "postgres_db_sg" {
  name = "postgres-db-sg"
  description = "Security group for PostgreSQL database"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "postgres_db_role" {
  name = "postgres-db-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}
```

