  acl    = "public-read"

  cors_rule {
    allowed_methods   = ["GET", "HEAD"]
    allowed_origins  = ["*"]
    allowed_headers  = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }

  lifecycle_rule {
    enabled = true
    id     = "delete-old-objects"
    prefix = "old/"
    expiration {
      days = 30
    }
  }
}

resource "aws_lightsail_distribution" "website_distribution" {
  bundle_id         = "nano_1_0"
  name              = "MyWebsiteDistribution"
  origin_public_dns = aws_s3_bucket.website_bucket.bucket_domain_name

  cache_behavior {
    behavior = "cache"
    path     = "/images/*"
  }

  cache_behavior {
    behavior = "cache"
    path     = "/css/*"
  }

  cache_behavior {
    behavior = "cache"
    path     = "/js/*"
  }

  cache_behavior {
    behavior = "cache"
    path     = "/*"
  }

  default_cache_behavior {
    behavior = "cache"
  }

  origin {
    name        = aws_s3_bucket.website_bucket.id
    region_name = aws_s3_bucket.website_bucket.region
    protocol_policy = "http-only"
  }

  timeouts {
    create = "60m"
    delete = "60m"
    update = "60m"
  }
}
```

