}

variable "subnets" {
  description = "List of subnet IDs for the Load Balancer"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-23456789"]
}

variable "security_groups" {
  description = "List of security group IDs for the Load Balancer"
  type        = list(string)
  default     = ["sg-12345678", "sg-23456789"]
}

resource "aws_lb" "my-load-balancer" {
  name               = "my-load-balancer"
  subnets             = var.subnets
  security_groups     = var.security_groups
  internal           = false
  load_balancer_type = "application"

  access_logs {
    bucket = "my-access-logs-bucket"
    enabled = true
    prefix = "alb-logs/"
  }

  connection_logs {
    bucket = "my-connection-logs-bucket"
    enabled = true
    prefix = "alb-logs/"
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}

resource "aws_alb_target_group" "my-target-group" {
  name               = "my-target-group"
  port               = 80
  protocol           = "HTTP"
  vpc_id             = aws_lb.my-load-balancer.vpc_id
  health_check {
    enabled   = true
    healthy_threshold = 2
    interval       = 30
    path           = "/"
    protocol       = "HTTP"
    timeout        = 10
    unhealthy_threshold = 2
  }
  stickiness {
    type = "lb_cookie"
    cookie_duration = 86400
    cookie_name = "my-cookie"
    enabled = true
  }
}
